package com.party.rgm36;
import org.json.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;
public class AuthorityTest{
 static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 static class Client implements AutoCloseable{
  final Socket socket;final InputStream in;final OutputStream out;final BlockingQueue<JSONObject> visuals=new LinkedBlockingQueue<>();
  Client(int port,String token)throws Exception{socket=new Socket("127.0.0.1",port);in=socket.getInputStream();out=socket.getOutputStream();out.write(("GET /ws?t="+token+" HTTP/1.1\r\nHost: 127.0.0.1:"+port+"\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n\r\n").getBytes(StandardCharsets.US_ASCII));out.flush();String line=RoomServer.line(in);check(line.contains("101"),"websocket upgrade");while(!(line=RoomServer.line(in)).isEmpty()){}Thread reader=new Thread(()->{try{while(true){int op=in.read(),length=in.read();if(op<0||length<0)break;long size=length&127;if(size==126){byte[] n=RoomServer.readExactly(in,2);size=(n[0]&255)*256+(n[1]&255);}else if(size==127){size=new DataInputStream(in).readLong();}check(size<=1048576,"bounded server frame");JSONObject packet=new JSONObject(new String(RoomServer.readExactly(in,(int)size),StandardCharsets.UTF_8));if(packet.optString("type").equals("visual"))visuals.add(packet);}}catch(Exception ignored){}},"authority-test-reader");reader.setDaemon(true);reader.start();}
  void send(JSONObject packet)throws Exception{byte[] bytes=packet.toString().getBytes(StandardCharsets.UTF_8),mask={1,2,3,4};out.write(129);if(bytes.length<126)out.write(128|bytes.length);else if(bytes.length<=65535){out.write(128|126);out.write(bytes.length>>8);out.write(bytes.length&255);}else{out.write(128|127);new DataOutputStream(out).writeLong(bytes.length);}out.write(mask);for(int i=0;i<bytes.length;i++)bytes[i]^=mask[i%4];out.write(bytes);out.flush();}
  public void close()throws IOException{socket.close();}void abort()throws IOException{close();}
 }
 static void send(Client ws,JSONObject data)throws Exception{ws.send(data);}
 static JSONObject packet(String type,RoomWorld w)throws Exception{return new JSONObject().put("type",type).put("epoch",w.epoch).put("resync",w.resync).put("stream",w.visualStream.isEmpty()?"authority-stream-1":w.visualStream);}
 static String partner(RoomWorld w)throws Exception{JSONObject c=w.autoCard(1);return w.autoPair(new JSONObject().put("protocol",AutoProtocol.ID).put("key",c.getString("key")).put("peerId","authority-device-b")).getString("token");}
 static void start(RoomWorld w,String g)throws Exception{w.input(w.hostToken,w.seats[0].link,packet("warm",w).put("protocol",AutoProtocol.ID));w.input(g,w.seats[1].link,packet("warm",w).put("protocol",AutoProtocol.ID));w.tick(System.currentTimeMillis());w.input(w.hostToken,w.seats[0].link,packet("engine",w).put("frame",0));w.input(g,w.seats[1].link,packet("engine",w).put("frame",0));}
 public static void main(String[]args)throws Exception{
  RoomWorld w=new RoomWorld();w.enableAutoElection("authority-device-a");w.enableAuthority();String g=partner(w);w.connect(w.hostToken,"h");w.connect(g,"g");start(w,g);long now=System.currentTimeMillis();for(int i=0;i<60;i++){w.input(w.hostToken,"h",packet("progress",w).put("frame",w.frame));w.tick(now);}check(w.frame==60,"guest progress must not gate authority clock");for(int i=0;i<20;i++)w.tick(now);check(w.frame==61,"host lead is bounded by two frames");
  w.input(w.hostToken,"h",packet("producer",w));JSONObject forged=packet("visual",w).put("frame",61).put("payload","[1,2]");w.input(g,"g",forged);check(w.latestVisual==null,"guest cannot propose authoritative state");w.input(w.hostToken,"h",forged);check(w.visualFrame==61,"host state accepted");String original=w.latestVisual.toString();w.input(w.hostToken,"h",packet("visual",w).put("frame",60).put("payload","[9]"));check(w.latestVisual.toString().equals(original),"old snapshot rejected");check(w.state(g).getJSONArray("commands").length()==0,"guest never receives simulation journal");check(w.visualFor(w.hostToken)==null,"visual delivery only to display peer");
  w.input(g,"g",packet("input",w).put("seq",1).put("mask",48));w.input(w.hostToken,"h",packet("controlGate",w).put("frame",w.frame).put("blocked",true));check(w.seats[1].mask==0,"intro clears both held inputs");w.input(g,"g",packet("input",w).put("seq",2).put("mask",48));check(w.seats[1].mask==0,"intro refuses stale held attacks");w.input(w.hostToken,"h",packet("progress",w).put("frame",w.frame));int introFrame=w.frame;w.tick(now);check(w.frame==introFrame+1,"input gate must not stop intro animation clock");w.input(w.hostToken,"h",packet("controlGate",w).put("frame",w.frame).put("blocked",false));w.input(g,"g",packet("controlGate",w).put("frame",w.frame).put("blocked",true));check(!w.rulesInputBlocked,"guest cannot lock player controls");
  try(RoomServer server=new RoomServer(n->new byte[0])){
   RoomWorld r=server.world;r.enableAutoElection("authority-device-a");r.enableAuthority();String token=partner(r);Client hc=new Client(server.port(),r.hostToken),gc=new Client(server.port(),token),hs=hc,gs=gc;
   send(hs,packet("warm",r).put("protocol",AutoProtocol.ID));send(gs,packet("warm",r).put("protocol",AutoProtocol.ID));long end=System.currentTimeMillis()+3000;while(!r.phase.equals("play")&&System.currentTimeMillis()<end)Thread.sleep(20);check(r.phase.equals("play"),"warm barrier started");
   send(hs,packet("producer",r));String large="中".repeat(25000);send(hs,packet("visual",r).put("frame",0).put("payload",large));JSONObject first=gc.visuals.poll(3,TimeUnit.SECONDS);check(first!=null&&first.getString("payload").equals(large),"RFC6455 64-bit UTF-8 visual frame roundtrip");
   send(hs,packet("engine",r).put("frame",0));send(gs,packet("engine",r).put("frame",0));end=System.currentTimeMillis()+3000;while(r.frame<2&&System.currentTimeMillis()<end)Thread.sleep(20);check(r.frame==2,"host-only progress bound");send(hs,packet("visual",r).put("frame",1).put("payload","[1]"));send(hs,packet("visual",r).put("frame",2).put("payload","[2]"));Thread.sleep(200);check(gc.visuals.isEmpty(),"one in-flight visual until applied acknowledgment");
   send(gs,packet("visualAck",r).put("frame",999));Thread.sleep(100);check(gc.visuals.isEmpty(),"forged future acknowledgment ignored");send(gs,packet("visualAck",r).put("frame",0));JSONObject latest=gc.visuals.poll(3,TimeUnit.SECONDS);check(latest!=null&&latest.getInt("frame")==2,"pending visual is replaced by latest frame");
   int epoch=r.epoch;r.action(new JSONObject().put("token",r.hostToken).put("op","reload").put("requestId","authority-reload"));check(r.latestVisual==null,"new game clears cached view");send(hs,new JSONObject().put("type","visual").put("epoch",epoch).put("resync",0).put("frame",0).put("payload","[0]"));Thread.sleep(100);check(r.latestVisual==null,"old epoch cannot restore stale world");send(hs,packet("producer",r));send(hs,packet("visual",r).put("frame",0).put("payload","[3]"));JSONObject fresh=gc.visuals.poll(3,TimeUnit.SECONDS);check(fresh!=null&&fresh.getInt("epoch")==r.epoch,"new epoch resets visual credit without old acknowledgment");hs.abort();gs.abort();
  }
  System.out.println("AUTHORITY PROTOCOL PASS: host-only state, host-only pacing, latest-only credit, stale epoch/ack rejection, large UTF-8 frames");
 }
}
